import React from 'react';

function Section1() {
  const styles = {
    // Global styles
    global: {
      margin: 0,
      padding: 0,
      boxSizing: 'border-box',
      fontFamily: "'Inter', 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif",
      lineHeight: 1.6,
      color: '#1a1a1a',
      backgroundColor: '#fafbfc'
    },

    // Header Styles
    header: {
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      color: 'white',
      boxShadow: '0 8px 32px rgba(0, 0, 0, 0.12)',
      position: 'relative',
      overflow: 'hidden'
    },

    headerOverlay: {
      position: 'absolute',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      background: 'rgba(0, 0, 0, 0.1)',
      zIndex: 0
    },

    logo: {
      position: 'relative',
      zIndex: 2,
      padding: '3rem 0 2rem',
      textAlign: 'center'
    },

    logoH1: {
      fontSize: '4rem',
      fontWeight: 300,
      letterSpacing: '0.02em',
      textShadow: '2px 4px 8px rgba(0, 0, 0, 0.3)',
      marginBottom: 0,
      lineHeight: 1.1,
      background: 'linear-gradient(45deg, #ffd700, #ffed4e)',
      WebkitBackgroundClip: 'text',
      WebkitTextFillColor: 'transparent',
      backgroundClip: 'text'
    },

    // Navigation Styles
    nav: {
      background: 'rgba(255, 255, 255, 0.95)',
      backdropFilter: 'blur(20px)',
      borderTop: '1px solid rgba(255, 255, 255, 0.2)',
      position: 'relative',
      zIndex: 2,
      boxShadow: '0 4px 20px rgba(0, 0, 0, 0.08)'
    },

    navUl: {
      display: 'flex',
      justifyContent: 'center',
      listStyle: 'none',
      margin: 0,
      padding: 0,
      gap: '2rem',
      maxWidth: '1200px',
      marginLeft: 'auto',
      marginRight: 'auto',
      paddingLeft: '2rem',
      paddingRight: '2rem'
    },

    navLi: {
      margin: 0
    },

    navLink: {
      display: 'block',
      padding: '1.25rem 2rem',
      color: '#2d3748',
      textDecoration: 'none',
      fontWeight: 600,
      fontSize: '1.1rem',
      transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
      position: 'relative',
      borderRadius: '8px',
      textAlign: 'center'
    },

    navLinkActive: {
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      color: 'white',
      boxShadow: '0 4px 12px rgba(102, 126, 234, 0.3)'
    },

    // Main Content Styles
    main: {
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      minHeight: '70vh',
      padding: '4rem 2rem',
      background: 'linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%)'
    },

    buttonContainer: {
      display: 'flex',
      gap: '3rem',
      justifyContent: 'center',
      alignItems: 'center',
      flexWrap: 'wrap'
    },

    patternButton: {
      display: 'flex',
      flexDirection: 'column',
      justifyContent: 'center',
      alignItems: 'center',
      width: '280px',
      height: '200px',
      background: 'linear-gradient(145deg, #ffffff, #f0f0f0)',
      border: '2px solid transparent',
      borderRadius: '24px',
      textDecoration: 'none',
      color: '#2d3748',
      fontSize: '1.5rem',
      fontWeight: 700,
      textAlign: 'center',
      lineHeight: 1.4,
      transition: 'all 0.4s cubic-bezier(0.4, 0, 0.2, 1)',
      boxShadow: '0 10px 30px rgba(0, 0, 0, 0.1)',
      position: 'relative',
      overflow: 'hidden',
      backgroundSize: '200% 200%',
      backgroundPosition: '0% 0%'
    },

    patternButtonHover: {
      transform: 'translateY(-8px) scale(1.05)',
      boxShadow: '0 20px 50px rgba(102, 126, 234, 0.3)',
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      color: 'white',
      borderColor: '#ffd700'
    },

    // Footer Styles
    footer: {
      background: 'linear-gradient(135deg, #1a202c 0%, #2d3748 100%)',
      color: 'white',
      position: 'relative',
      overflow: 'hidden',
      marginTop: '4rem'
    },

    footerOverlay: {
      position: 'absolute',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      background: 'rgba(0, 0, 0, 0.2)',
      zIndex: 0
    },

    footerContent: {
      position: 'relative',
      zIndex: 2,
      display: 'grid',
      gridTemplateColumns: '1fr auto 1fr',
      gap: '3rem',
      maxWidth: '1200px',
      margin: '0 auto',
      padding: '4rem 2rem 2rem',
      alignItems: 'start'
    },

    footerLeft: {
      textAlign: 'left'
    },

    footerH3: {
      fontSize: '1.8rem',
      fontWeight: 800,
      marginBottom: '1rem',
      color: '#ffd700',
      textShadow: '0 2px 4px rgba(255, 215, 0, 0.3)'
    },

    footerDescription: {
      fontSize: '1rem',
      lineHeight: 1.6,
      color: '#cbd5e0',
      opacity: 0.9
    },

    socialStickers: {
      display: 'grid',
      gridTemplateColumns: 'repeat(2, 1fr)',
      gap: '1rem',
      alignItems: 'center',
      justifyItems: 'center'
    },

    socialLink: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      width: '50px',
      height: '50px',
      background: 'rgba(255, 255, 255, 0.1)',
      borderRadius: '12px',
      transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
      backdropFilter: 'blur(10px)',
      border: '1px solid rgba(255, 255, 255, 0.1)',
      textDecoration: 'none'
    },

    socialImg: {
      width: '24px',
      height: '24px',
      filter: 'brightness(0) invert(1)',
      objectFit: 'contain'
    },

    footerRight: {
      textAlign: 'right'
    },

    footerRightP: {
      fontSize: '1rem',
      marginBottom: '0.5rem',
      color: '#cbd5e0'
    },

    contactLink: {
      color: '#ffd700',
      textDecoration: 'none',
      fontWeight: 600,
      transition: 'all 0.3s ease'
    },

    copyright: {
      fontSize: '0.9rem',
      color: '#a0aec0',
      fontWeight: 300,
      marginTop: '0.5rem'
    }
  };

  // Media queries handled through JavaScript
  const isMobile = window.innerWidth <= 768;
  const isTablet = window.innerWidth <= 968 && window.innerWidth > 768;

  // Responsive style adjustments
  if (isMobile) {
    styles.logoH1.fontSize = '2.5rem';
    styles.navUl.flexDirection = 'column';
    styles.navUl.gap = '0';
    styles.buttonContainer.flexDirection = 'column';
    styles.buttonContainer.gap = '2rem';
    styles.patternButton.width = '260px';
    styles.patternButton.height = '180px';
    styles.patternButton.fontSize = '1.3rem';
    styles.footerContent.gridTemplateColumns = '1fr';
    styles.footerContent.gap = '2rem';
    styles.footerContent.textAlign = 'center';
    styles.footerLeft.textAlign = 'center';
    styles.footerRight.textAlign = 'center';
    styles.main.padding = '2rem 1rem';
  }

  if (isTablet) {
    styles.logoH1.fontSize = '3.2rem';
    styles.buttonContainer.gap = '2.5rem';
  }

  return (
    <>
      <style>
        {`
          * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
          }
          
          body {
            font-family: 'Inter', 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif;
            line-height: 1.6;
            color: #1a1a1a;
            background-color: #fafbfc;
          }

          .nav-link:hover {
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%) !important;
            color: white !important;
            transform: translateY(-2px) !important;
            box-shadow: 0 8px 20px rgba(102, 126, 234, 0.3) !important;
          }

          .pattern-button:hover {
            transform: translateY(-8px) scale(1.05) !important;
            box-shadow: 0 20px 50px rgba(102, 126, 234, 0.3) !important;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%) !important;
            color: white !important;
            border-color: #ffd700 !important;
          }

          .social-link:hover {
            background: rgba(255, 255, 255, 0.2) !important;
            transform: translateY(-3px) scale(1.1) !important;
            box-shadow: 0 8px 20px rgba(0, 0, 0, 0.2) !important;
          }

          .contact-link:hover {
            color: #fff !important;
            text-shadow: 0 0 5px #ffd700 !important;
          }

          @media (max-width: 968px) {
            .footer-content {
              grid-template-columns: 1fr !important;
              gap: 2rem !important;
              text-align: center !important;
            }
            .footer-left, .footer-right {
              text-align: center !important;
            }
          }

          @media (max-width: 768px) {
            .logo h1 {
              font-size: 2.5rem !important;
            }
            .nav ul {
              flex-direction: column !important;
              gap: 0 !important;
            }
            .button-container {
              flex-direction: column !important;
              gap: 2rem !important;
            }
            .pattern-button {
              width: 260px !important;
              height: 180px !important;
              font-size: 1.3rem !important;
            }
            main {
              padding: 2rem 1rem !important;
            }
          }

          @media (max-width: 480px) {
            .logo h1 {
              font-size: 2rem !important;
            }
            .pattern-button {
              width: 240px !important;
              height: 160px !important;
              font-size: 1.2rem !important;
            }
            .footer-content {
              padding: 3rem 1rem 2rem !important;
            }
          }
        `}
      </style>

      <header style={styles.header}>
        <div style={styles.headerOverlay}></div>
        <div style={styles.logo} className="logo">
          <h1 style={styles.logoH1}>SonicGLow<br />Cube</h1>
        </div>
        <nav style={styles.nav}>
          <ul style={styles.navUl}>
            <li style={styles.navLi}>
              <a href="/" style={styles.navLink} className="nav-link">Home</a>
            </li>
            <li style={styles.navLi}>
              <a href="/resources" style={styles.navLink} className="nav-link">Resources</a>
            </li>
            <li style={styles.navLi}>
              <a href="/cube" style={styles.navLink} className="nav-link">SonicGlow Cube</a>
            </li>
            <li style={styles.navLi}>
              <a 
                href="/about" 
                style={{...styles.navLink, ...styles.navLinkActive}} 
                className="nav-link active"
              >
                About Us
              </a>
            </li>
          </ul>
        </nav>
      </header>

      <main style={styles.main}>
        <div style={styles.buttonContainer} className="button-container">
          <a 
            href="/Predefined" 
            style={styles.patternButton} 
            className="pattern-button"
          >
            Pre Defined<br />Patterns
          </a>
          <a 
            href="/Userdefined" 
            style={styles.patternButton} 
            className="pattern-button"
          >
            User Defined<br />Patterns
          </a>
        </div>
      </main>

      <footer style={styles.footer}>
        <div style={styles.footerOverlay}></div>
        <div style={styles.footerContent} className="footer-content">
          <div style={styles.footerLeft} className="footer-left">
            <h3 style={styles.footerH3}>SonicGlow Cube</h3>
            <p style={styles.footerDescription}>
              Created by Hardware Hackers<br />
              University of Moratuwa – First-Year Hardware Project
            </p>
          </div>
          <div style={styles.socialStickers} className="social-stickers">
            <a 
              href="https://www.facebook.com/" 
              target="_blank" 
              rel="noopener noreferrer"
              style={styles.socialLink}
              className="social-link"
            >
              <img src="/images/fb.png" alt="Facebook" style={styles.socialImg} />
            </a>
            <a 
              href="https://www.youtube.com/" 
              target="_blank" 
              rel="noopener noreferrer"
              style={styles.socialLink}
              className="social-link"
            >
              <img src="/images/youtube.png" alt="YouTube" style={styles.socialImg} />
            </a>
            <a 
              href="https://www.linkedin.com/" 
              target="_blank" 
              rel="noopener noreferrer"
              style={styles.socialLink}
              className="social-link"
            >
              <img src="/images/linkedin.png" alt="LinkedIn" style={styles.socialImg} />
            </a>
            <a 
              href="https://www.instagram.com/" 
              target="_blank" 
              rel="noopener noreferrer"
              style={styles.socialLink}
              className="social-link"
            >
              <img src="/images/inst.png" alt="Instagram" style={styles.socialImg} />
            </a>
          </div>
          <div style={styles.footerRight} className="footer-right">
            <p style={styles.footerRightP}>
              Contact us: 
              <a 
                href="mailto:hardwarehackers@uom.lk"
                style={styles.contactLink}
                className="contact-link"
              >
                hardwarehackers@uom.lk
              </a>
            </p>
            <p style={styles.copyright}>
              © 2025 SonicGlow Cube | All rights reserved
            </p>
          </div>
        </div>
      </footer>
    </>
  );
}

export default Section1;
